(() => {
  "use strict";
  const mapDocBase64 = "";
  let loaded = false;
  const getFrame = () => document.getElementById('integratedMapFrame');
  window.loadIntegratedMaumMap = () => {
    const target = getFrame();
    if (!target) return;
    target.style.height = '100%';
    target.style.minHeight = '0';
    if (loaded) {
      try { target.contentWindow && target.contentWindow.dispatchEvent(new Event('resize')); } catch (_) {}
      return;
    }
    try {
      const binary = atob(mapDocBase64);
      const bytes = new Uint8Array(binary.length);
      for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
      const html = new TextDecoder('utf-8').decode(bytes);
      target.srcdoc = html;
      loaded = true;
    } catch (error) {
      console.error('마음지도를 불러오지 못했습니다.', error);
      target.srcdoc = '<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><body style="font-family:sans-serif;padding:24px;color:#5d6f5e">지도를 표시하지 못했습니다. 페이지를 새로고침한 뒤 다시 시도해 주세요.</body></html>';
    }
  };
})();
